tool_calls:
mkdir -p /home/eval/recon/out
cat > /home/eval/recon/out/reconcile.awk <<'AWK'
# Amounts are converted from digit strings to integer cents before arithmetic.
function cents(s,    sign,p,n,whole,fraction) {
    gsub(/,/, "", s)
    sign = 1
    if (substr(s,1,1) == "-") { sign = -1; s = substr(s,2) }
    else if (substr(s,1,1) == "+") s = substr(s,2)
    if (s !~ /^[0-9]+(\.[0-9]{1,3})?$/) {
        # Also works with awk implementations without interval expressions.
        if (s !~ /^[0-9]+(\.[0-9][0-9]?[0-9]?)?$/) fail("Invalid amount: " s)
    }
    n = split(s,p,".")
    whole = p[1] + 0
    fraction = (n == 2 ? p[2] : "")
    if (length(fraction) == 3 && substr(fraction,3,1) != "0")
        fail("Amount is not exact to the cent: " s)
    fraction = substr(fraction "00",1,2) + 0
    return sign * (whole * 100 + fraction)
}
function money(v,    sign) {
    sign = v < 0 ? "-" : ""
    if (v < 0) v = -v
    return sign sprintf("%d.%02d",int(v/100),v%100)
}
function fail(message) { print message > "/dev/stderr"; failed=1; exit 1 }
function ledger_record(    id,v) {
    if (!ledger_header++) {
        if (nf != 4 || fields[1] != "txn_id") fail("Invalid ledger header")
    } else {
        if (nf != 4) fail("Invalid ledger field count")
        id = fields[1]; v = cents(fields[4])
        if (id in la) fail("Duplicate ledger id: " id)
        la[id] = v; ld[id] = fields[2]; lt += v; ln++
        ids[id] = 1
    }
    delete fields; nf=1; field=""
}
BEGIN { nf=1 }
FILENAME == ARGV[1] {
    line=$0; sub(/\r$/, "", line)
    for (i=1; i<=length(line); i++) {
        ch=substr(line,i,1)
        if (quoted) {
            if (ch == "\"") {
                if (substr(line,i+1,1) == "\"") { field=field "\""; i++ }
                else quoted=0
            } else field=field ch
        } else if (ch == "\"") quoted=1
        else if (ch == ",") { fields[nf++]=field; field="" }
        else field=field ch
    }
    if (quoted) field=field "\n"
    else { fields[nf]=field; ledger_record() }
    next
}
FILENAME == ARGV[2] {
    if (quoted) fail("Unterminated quoted CSV field")
    line=$0; sub(/\r$/, "", line)
    if (!bank_header++) next
    if (split(line,b,"\t") != 4) fail("Invalid bank field count")
    id=b[1]; gsub(/^ +| +$/, "", id); id=toupper(id)
    split(b[2],d,"/"); date=d[3] "-" d[2] "-" d[1]
    v=cents(b[4]); key=id SUBSEP date SUBSEP v
    if (key in seen) { duplicates++; next }
    seen[key]=1
    if (id in ba) fail("Nonduplicate bank ref is not unique: " id)
    ba[id]=v; bd[id]=date; bt+=v; bn++; ids[id]=1
}
END {
    if (failed) exit 1
    if (quoted) fail("Unterminated quoted CSV field")
    # String-order insertion sort, independent of awk array iteration order.
    for (id in ids) {
        j=++total_ids
        while (j>1 && ("x" ordered[j-1]) > ("x" id)) {
            ordered[j]=ordered[j-1]; j--
        }
        ordered[j]=id
    }
    for (i=1; i<=total_ids; i++) {
        id=ordered[i]
        if (!(id in ba)) missing_bank++
        else if (!(id in la)) missing_ledger++
        else {
            if (la[id] != ba[id]) amount_mismatch++
            if (ld[id] != bd[id]) date_mismatch++
            if (la[id] == ba[id] && ld[id] == bd[id]) matched++
        }
    }
    printf "ledger_rows: %d\nbank_rows: %d\nduplicate_bank_rows: %d\n",ln,bn,duplicates
    printf "ledger_total: %s\nbank_total: %s\nmatched: %d\n",money(lt),money(bt),matched
    printf "amount_mismatch: %d\n",amount_mismatch
    for (i=1; i<=total_ids; i++) {
        id=ordered[i]
        if ((id in la) && (id in ba) && la[id]!=ba[id])
            printf "  %s ledger=%s bank=%s\n",id,money(la[id]),money(ba[id])
    }
    printf "date_mismatch: %d\n",date_mismatch
    for (i=1; i<=total_ids; i++) {
        id=ordered[i]
        if ((id in la) && (id in ba) && ld[id]!=bd[id])
            printf "  %s ledger=%s bank=%s\n",id,ld[id],bd[id]
    }
    printf "missing_in_bank: %d\n",missing_bank
    for (i=1; i<=total_ids; i++) if (!(ordered[i] in ba)) printf "  %s\n",ordered[i]
    printf "missing_in_ledger: %d\n",missing_ledger
    for (i=1; i<=total_ids; i++) if (!(ordered[i] in la)) printf "  %s\n",ordered[i]
}
AWK
awk -f /home/eval/recon/out/reconcile.awk /home/eval/recon/ledger.csv /home/eval/recon/bank.tsv > /home/eval/recon/out/reconciliation.tmp && mv /home/eval/recon/out/reconciliation.tmp /home/eval/recon/out/reconciliation.txt
cat /home/eval/recon/out/reconciliation.txt

